import type { Context } from '@netlify/edge-functions';
// Generated by scripts/deploy.sh (gitignored). Holds only a SHA-256 hex of "user:pass".
import { AUTH_HASH } from '../edge-lib/auth_hash.ts';

const encoder = new TextEncoder();

function constantTimeEquals(a: string, b: string): boolean {
  const aBytes = encoder.encode(a);
  const bBytes = encoder.encode(b);
  const maxLength = Math.max(aBytes.length, bBytes.length);
  const aPadded = new Uint8Array(maxLength);
  const bPadded = new Uint8Array(maxLength);
  aPadded.set(aBytes);
  bPadded.set(bBytes);
  let mismatch = 0;

  for (let i = 0; i < maxLength; i += 1) {
    mismatch |= aPadded[i] ^ bPadded[i];
  }

  mismatch |= aBytes.length ^ bBytes.length;

  return mismatch === 0;
}

// Both deployments (londontrafficdemo, nationaltrafficdemo) use this one
// function: credentials come from the site's BASIC_AUTH_CREDENTIALS env var,
// with the deploy-time baked hash as fallback. Neither present -> deny everyone.
export default async (request: Request, context: Context) => {
  const pathname = new URL(request.url).pathname;
  if (pathname === '/.netlify' || pathname.startsWith('/.netlify/')) {
    return await context.next();
  }

  const credentials = Deno.env.get('BASIC_AUTH_CREDENTIALS');
  const bakedHash = typeof AUTH_HASH === 'string' ? AUTH_HASH : '';

  if (!credentials && !bakedHash) {
    return new Response('Unauthorized: no credentials are configured', {
      status: 401,
      headers: { 'WWW-Authenticate': 'Basic realm="Traffic estimates"' },
    });
  }

  const authHeader = request.headers.get('Authorization');

  if (authHeader) {
    const [scheme, encoded] = authHeader.split(' ');
    if (scheme?.toLowerCase() === 'basic' && encoded) {
      try {
        const decoded = atob(encoded);
        if (credentials) {
          const allowedCredentials = credentials.split(' ').filter(Boolean);
          let authMatch = 0;
          for (const allowedCredential of allowedCredentials) {
            authMatch |= constantTimeEquals(allowedCredential, decoded) ? 1 : 0;
          }
          if (authMatch === 1) {
            return await context.next();
          }
        } else {
          const digest = await crypto.subtle.digest('SHA-256', encoder.encode(decoded));
          const hex = Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, '0')).join('');
          if (constantTimeEquals(hex, bakedHash)) {
            return await context.next();
          }
        }
      } catch {
        // Malformed base64 - treat as unauthorized
      }
    }
  }

  return new Response('Unauthorized', {
    status: 401,
    headers: {
      'WWW-Authenticate': 'Basic realm="Traffic estimates"',
    },
  });
};
